//! The vanilla look: textures and the painting primitives built on them.
//!
//! All art is original and generated by tools/gen_skin.py. Only a handful of
//! textures are used and they're decoded once, so this costs almost nothing
//! after startup, and nothing at all while idle.

use crate::theme;
use eframe::egui::{
    self, Align2, Color32, ColorImage, FontId, Mesh, Painter, Pos2, Rect, Shape, Stroke,
    StrokeKind, TextureFilter, TextureHandle, TextureOptions, TextureWrapMode, epaint::Vertex,
    pos2, vec2,
};

fn decode(bytes: &[u8]) -> ColorImage {
    let img = image::load_from_memory_with_format(bytes, image::ImageFormat::Png)
        .expect("embedded skin textures are valid PNGs")
        .into_rgba8();
    let size = [img.width() as usize, img.height() as usize];
    ColorImage::from_rgba_unmultiplied(size, img.as_raw())
}

pub struct Skin {
    stone: TextureHandle,
    parchment: TextureHandle,
    corner: TextureHandle,
    edge: TextureHandle,
    ring: TextureHandle,
    spark: TextureHandle,
    pub logo: TextureHandle,
    pub logo_off: TextureHandle,
}

impl Skin {
    pub fn load(ctx: &egui::Context) -> Self {
        let repeat = TextureOptions {
            magnification: TextureFilter::Linear,
            minification: TextureFilter::Linear,
            wrap_mode: TextureWrapMode::Repeat,
            mipmap_mode: None,
        };
        let clamp = TextureOptions::LINEAR;
        let crisp = TextureOptions::NEAREST;
        let load =
            |name: &str, bytes: &[u8], options| ctx.load_texture(name, decode(bytes), options);
        Self {
            stone: load(
                "stone",
                include_bytes!("../../../assets/skin/stone.png"),
                repeat,
            ),
            parchment: load(
                "parchment",
                include_bytes!("../../../assets/skin/parchment.png"),
                repeat,
            ),
            corner: load(
                "corner",
                include_bytes!("../../../assets/skin/corner.png"),
                clamp,
            ),
            edge: load(
                "edge",
                include_bytes!("../../../assets/skin/edge.png"),
                repeat,
            ),
            ring: load(
                "ring",
                include_bytes!("../../../assets/skin/ring.png"),
                clamp,
            ),
            spark: load(
                "spark",
                include_bytes!("../../../assets/skin/spark.png"),
                clamp,
            ),
            logo: load(
                "logo",
                include_bytes!("../../../assets/icon/png/icon-32.png"),
                crisp,
            ),
            logo_off: load(
                "logo-off",
                include_bytes!("../../../assets/icon/png/icon-off-32.png"),
                crisp,
            ),
        }
    }

    fn tile(&self, painter: &Painter, rect: Rect, tex: &TextureHandle, scale: f32, tint: Color32) {
        let size = tex.size_vec2() * scale;
        let uv = Rect::from_min_max(
            pos2(rect.min.x / size.x, rect.min.y / size.y),
            pos2(rect.max.x / size.x, rect.max.y / size.y),
        );
        let mut mesh = Mesh::with_texture(tex.id());
        mesh.add_rect_with_uv(rect, uv, tint);
        painter.add(Shape::mesh(mesh));
    }

    /// The dark slate behind everything.
    pub fn stone(&self, painter: &Painter, rect: Rect) {
        self.tile(painter, rect, &self.stone, 1.0, Color32::WHITE);
    }

    /// Aged paper with darkened edges.
    pub fn parchment(&self, painter: &Painter, rect: Rect) {
        self.tile(painter, rect, &self.parchment, 1.0, Color32::WHITE);
        let burn = Color32::from_rgba_unmultiplied(74, 44, 14, 90);
        let w = 26.0_f32.min(rect.width() / 3.0);
        let clear = Color32::TRANSPARENT;
        h_gradient(
            painter,
            Rect::from_min_size(rect.min, vec2(w, rect.height())),
            burn,
            clear,
        );
        h_gradient(
            painter,
            Rect::from_min_max(pos2(rect.max.x - w, rect.min.y), rect.max),
            clear,
            burn,
        );
        v_gradient(
            painter,
            Rect::from_min_size(rect.min, vec2(rect.width(), w)),
            burn,
            clear,
        );
        v_gradient(
            painter,
            Rect::from_min_max(pos2(rect.min.x, rect.max.y - w), rect.max),
            clear,
            burn,
        );
    }

    /// The heavy gold window frame: tiled trim plus an ornament in each corner.
    pub fn gold_frame(&self, painter: &Painter, rect: Rect) {
        let thick = 8.0;
        let tex = self.edge.size_vec2();
        let u = |len: f32| len * (thick / tex.y) / tex.x * (tex.y / thick);
        let add_h = |y: f32, flip: bool| {
            let r = Rect::from_min_size(pos2(rect.min.x, y), vec2(rect.width(), thick));
            let (v0, v1) = if flip { (1.0, 0.0) } else { (0.0, 1.0) };
            let mut m = Mesh::with_texture(self.edge.id());
            m.add_rect_with_uv(
                r,
                Rect::from_min_max(pos2(0.0, v0), pos2(u(rect.width()), v1)),
                Color32::WHITE,
            );
            painter.add(Shape::mesh(m));
        };
        add_h(rect.min.y, false);
        add_h(rect.max.y - thick, true);

        // Vertical runs reuse the horizontal strip with u and v swapped.
        let add_v = |x: f32, flip: bool| {
            let r = Rect::from_min_size(pos2(x, rect.min.y), vec2(thick, rect.height()));
            let (v0, v1) = if flip { (1.0, 0.0) } else { (0.0, 1.0) };
            let end = u(rect.height());
            let mut m = Mesh::with_texture(self.edge.id());
            let i = m.vertices.len() as u32;
            let quad = [
                (r.left_top(), pos2(0.0, v0)),
                (r.right_top(), pos2(0.0, v1)),
                (r.right_bottom(), pos2(end, v1)),
                (r.left_bottom(), pos2(end, v0)),
            ];
            for (pos, uv) in quad {
                m.vertices.push(Vertex {
                    pos,
                    uv,
                    color: Color32::WHITE,
                });
            }
            m.indices.extend([i, i + 1, i + 2, i, i + 2, i + 3]);
            painter.add(Shape::mesh(m));
        };
        add_v(rect.min.x, false);
        add_v(rect.max.x - thick, true);

        let size = 64.0;
        let flips = [
            (rect.left_top(), false, false),
            (pos2(rect.max.x - size, rect.min.y), true, false),
            (pos2(rect.min.x, rect.max.y - size), false, true),
            (pos2(rect.max.x - size, rect.max.y - size), true, true),
        ];
        for (at, flip_x, flip_y) in flips {
            let (u0, u1) = if flip_x { (1.0, 0.0) } else { (0.0, 1.0) };
            let (v0, v1) = if flip_y { (1.0, 0.0) } else { (0.0, 1.0) };
            painter.image(
                self.corner.id(),
                Rect::from_min_size(at, vec2(size, size)),
                Rect::from_min_max(pos2(u0, v0), pos2(u1, v1)),
                Color32::WHITE,
            );
        }
    }

    /// The round portrait with the CRT sitting inside a gold bezel.
    pub fn portrait(&self, painter: &Painter, center: Pos2, radius: f32, screen_off: bool) {
        painter.circle_filled(center, radius - 3.0, Color32::from_rgb(9, 24, 44));
        let tex = if screen_off {
            &self.logo_off
        } else {
            &self.logo
        };
        // Exactly 2x the 32px art, so the pixels stay square at normal scale.
        let logo = 64.0;
        painter.image(
            tex.id(),
            Rect::from_center_size(center.round(), vec2(logo, logo)),
            Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
            Color32::WHITE,
        );
        painter.image(
            self.ring.id(),
            Rect::from_center_size(center, vec2(radius * 2.0, radius * 2.0)),
            Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
            Color32::WHITE,
        );
    }

    /// The casting bar: gold fill, a spark at its head, and centered text.
    pub fn casting_bar(&self, painter: &Painter, rect: Rect, fraction: f32, text: &str) {
        painter.rect_filled(rect, 2.0, Color32::BLACK);
        let inner = rect.shrink(2.0);
        let fill_w = inner.width() * fraction.clamp(0.0, 1.0);
        let fill = Rect::from_min_size(inner.min, vec2(fill_w, inner.height()));
        v_gradient(
            painter,
            fill,
            Color32::from_rgb(241, 190, 40),
            Color32::from_rgb(170, 112, 8),
        );
        if fraction > 0.0 && fraction < 1.0 {
            let spark = Rect::from_center_size(
                pos2(fill.max.x, inner.center().y),
                vec2(14.0, rect.height() * 2.2),
            );
            painter.image(
                self.spark.id(),
                spark,
                Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
                Color32::WHITE,
            );
        }
        painter.rect_stroke(
            rect,
            2.0,
            Stroke::new(1.5, Color32::from_rgb(142, 142, 154)),
            StrokeKind::Inside,
        );
        shadow_text(
            painter,
            rect.center(),
            Align2::CENTER_CENTER,
            text,
            theme::strong(13.5),
            Color32::WHITE,
        );
    }
}

/// A rectangle whose color runs from `top` to `bottom`.
pub fn v_gradient(painter: &Painter, rect: Rect, top: Color32, bottom: Color32) {
    quad(painter, rect, [top, top, bottom, bottom]);
}

/// A rectangle whose color runs from `left` to `right`.
pub fn h_gradient(painter: &Painter, rect: Rect, left: Color32, right: Color32) {
    quad(painter, rect, [left, right, right, left]);
}

/// Corners in order: left-top, right-top, right-bottom, left-bottom.
fn quad(painter: &Painter, rect: Rect, colors: [Color32; 4]) {
    let mut mesh = Mesh::default();
    let at = [
        rect.left_top(),
        rect.right_top(),
        rect.right_bottom(),
        rect.left_bottom(),
    ];
    for (pos, color) in at.into_iter().zip(colors) {
        mesh.colored_vertex(pos, color);
    }
    mesh.add_triangle(0, 1, 2);
    mesh.add_triangle(0, 2, 3);
    painter.add(Shape::mesh(mesh));
}

/// Text with the one-pixel black shadow every 2004 UI had.
pub fn shadow_text(
    painter: &Painter,
    pos: Pos2,
    align: Align2,
    text: &str,
    font: FontId,
    color: Color32,
) -> Rect {
    painter.text(
        pos + vec2(1.0, 1.0),
        align,
        text,
        font.clone(),
        theme::SHADOW,
    );
    painter.text(pos, align, text, font, color)
}

/// A sunken black well with a dark outer line and a thin gold inner line.
pub fn well(painter: &Painter, rect: Rect, fill: Color32) {
    painter.rect_filled(rect, 1.0, fill);
    painter.rect_stroke(
        rect,
        1.0,
        Stroke::new(1.0, Color32::from_black_alpha(220)),
        StrokeKind::Outside,
    );
    painter.rect_stroke(
        rect,
        1.0,
        Stroke::new(1.0, theme::GOLD_LINE),
        StrokeKind::Inside,
    );
}

/// A thin gold rule for dividing a frame into sections.
pub fn rule(painter: &Painter, from: Pos2, to: Pos2) {
    painter.line_segment([from, to], Stroke::new(1.0, Color32::from_black_alpha(200)));
    painter.line_segment(
        [from + vec2(0.0, 1.0), to + vec2(0.0, 1.0)],
        Stroke::new(1.0, theme::GOLD_LINE),
    );
}
